const fs = require('fs');
const https = require('https');

// Read and parse the vault-audit.txt file
const content = fs.readFileSync('vault-audit.txt', 'utf8');
const lines = content.split('\n');

// Extract environment variables (skip comments and empty lines)
const envVars = {};
lines.forEach(line => {
    if (line && !line.startsWith('#') && line.includes('=')) {
        const [key, value] = line.split('=', 2);
        envVars[key.trim()] = value.trim();
    }
});

// Prepare the JSON payload
const payload = JSON.stringify({
    timestamp: new Date().toISOString(),
    source: 'vault-audit.txt',
    environment_variables: envVars
});

// HTTP request options
const options = {
    hostname: 'localhost',
    port: 3003,
    path: '/api/vault-check',
    method: 'POST',
    headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
    }
};

// Make the request
const req = https.request(options, (res) => {
    console.log(`Status Code: ${res.statusCode}`);

    let responseData = '';
    res.on('data', (chunk) => {
        responseData += chunk;
    });

    res.on('end', () => {
        console.log('Response:', responseData);
        console.log('Vault check completed successfully');
    });
});

req.on('error', (error) => {
    console.error('Error making request:', error.message);
});

// Send the payload
req.write(payload);
req.end();

console.log('Sending vault check request...');
console.log('Payload:', payload);

