// Environment variable validation script
// Run this before starting the application to ensure all required env vars are set

require('dotenv').config();

const requiredEnvVars = [
  'NODE_ENV',
  'PORT',
  'SESSION_SECRET',
  'JWT_SECRET'
];

const recommendedEnvVars = [
  'DATABASE_URL',
  'AWS_ACCESS_KEY_ID',
  'AWS_SECRET_ACCESS_KEY',
  'STRIPE_SECRET_KEY'
];

const optionalEnvVars = [
  'BCRYPT_SALT_ROUNDS',
  'RATE_LIMIT_WINDOW_MS',
  'RATE_LIMIT_MAX_REQUESTS',
  'LOG_LEVEL'
];

function validateEnvironment() {
  console.log('🔍 Validating environment variables...\n');

  let hasErrors = false;

  // Check required variables
  console.log('📋 Required Environment Variables:');
  requiredEnvVars.forEach(varName => {
    if (!process.env[varName]) {
      console.log(`❌ ${varName}: MISSING - This is required for the application to run`);
      hasErrors = true;
    } else if (process.env[varName].includes('example') || process.env[varName].includes('your-')) {
      console.log(`⚠️  ${varName}: USING DEFAULT VALUE - Please set a proper value for production`);
    } else {
      console.log(`✅ ${varName}: SET`);
    }
  });

  console.log('\n📋 Recommended Environment Variables:');
  recommendedEnvVars.forEach(varName => {
    if (!process.env[varName]) {
      console.log(`⚠️  ${varName}: NOT SET - Recommended for production use`);
    } else if (process.env[varName].includes('example') || process.env[varName].includes('your-')) {
      console.log(`⚠️  ${varName}: USING DEFAULT/TEST VALUE`);
    } else {
      console.log(`✅ ${varName}: SET`);
    }
  });

  console.log('\n📋 Security Check:');

  // Check for default/common insecure values
  const insecurePatterns = [
    'secret123', 'password', '123456', 'admin', 'test', 'temp', 'changeme'
  ];

  requiredEnvVars.concat(recommendedEnvVars).forEach(varName => {
    const value = process.env[varName] || '';
    if (value && insecurePatterns.some(pattern => 
        value.toLowerCase().includes(pattern.toLowerCase()))) {
      console.log(`🔴 ${varName}: INSECURE VALUE DETECTED - Contains common insecure pattern`);
      hasErrors = true;
    }
  });

  // Check if in production but using development values
  if (process.env.NODE_ENV === 'production') {
    console.log('\n🏭 Production Environment Checks:');

    if (process.env.DATABASE_URL && process.env.DATABASE_URL.includes('localhost')) {
      console.log('🔴 DATABASE_URL: Using localhost in production environment');
      hasErrors = true;
    }

    if (process.env.ALLOWED_ORIGINS && process.env.ALLOWED_ORIGINS.includes('localhost')) {
      console.log('🔴 ALLOWED_ORIGINS: Contains localhost in production');
      hasErrors = true;
    }

    recommendedEnvVars.forEach(varName => {
      if (!process.env[varName]) {
        console.log(`🔴 ${varName}: MISSING IN PRODUCTION - This should be set for production use`);
        hasErrors = true;
      }
    });
  }

  console.log('\n' + '='.repeat(50));

  if (hasErrors) {
    console.log('❌ Environment validation FAILED');
    console.log('Please fix the issues above before starting the application');
    process.exit(1);
  } else {
    console.log('✅ Environment validation PASSED');
    console.log('Application can start safely');
  }
}

// Run validation if this script is executed directly
if (require.main === module) {
  validateEnvironment();
}

module.exports = { validateEnvironment, requiredEnvVars, recommendedEnvVars };

