// Environment variable format validation
require('dotenv').config();

const formatValidators = {
  // AWS Credentials
  AWS_ACCESS_KEY_ID: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = /^AKIA[0-9A-Z]{16}$/.test(value);
    return {
      valid: isValid,
      message: isValid ? 'Valid AWS access key format' : 'Should start with AKIA and be 20 characters'
    };
  },

  AWS_SECRET_ACCESS_KEY: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = /^[0-9a-zA-Z/+]{40}$/.test(value);
    return {
      valid: isValid,
      message: isValid ? 'Valid AWS secret format' : 'Should be 40 character base64 string'
    };
  },

  // Stripe Keys
  STRIPE_SECRET_KEY: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = /^(sk-live-|sk-test-)[a-zA-Z0-9]+$/.test(value);
    return {
      valid: isValid,
      message: isValid ? 'Valid Stripe secret key format' : 'Should start with sk-live- or sk-test-'
    };
  },

  STRIPE_PUBLISHABLE_KEY: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = /^(pk_live_|pk_test_)[a-zA-Z0-9]+$/.test(value);
    return {
      valid: isValid,
      message: isValid ? 'Valid Stripe publishable key format' : 'Should start with pk_live_ or pk_test_'
    };
  },

  // Database
  DATABASE_URL: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = /^[a-z]+:\/\/[^:]+:[^@]+@[^:\/]+:[0-9]+\/.+$/.test(value);
    return {
      valid: isValid,
      message: isValid ? 'Valid database URL format' : 'Should be protocol://user:pass@host:port/db'
    };
  },

  // Authentication Secrets
  SESSION_SECRET: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = value.length >= 32 && !value.includes(' ');
    return {
      valid: isValid,
      message: isValid ? 'Strong secret format' : 'Should be at least 32 random characters'
    };
  },

  JWT_SECRET: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = value.length >= 32 && !value.includes(' ');
    return {
      valid: isValid,
      message: isValid ? 'Strong JWT secret format' : 'Should be at least 32 random characters'
    };
  },

  // API Keys (generic validation)
  ANTHROPIC_API_KEY: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = value.length >= 20 && value.startsWith('sk-ant-');
    return {
      valid: isValid,
      message: isValid ? 'Valid Anthropic API key format' : 'Should start with sk-ant- and be at least 20 chars'
    };
  },

  OPENAI_API_KEY: (value) => {
    if (!value) return { valid: false, message: 'Missing value' };
    if (value.includes('your-') || value.includes('example')) 
      return { valid: false, message: 'Placeholder value' };

    const isValid = value.length >= 20 && value.startsWith('sk-');
    return {
      valid: isValid,
      message: isValid ? 'Valid OpenAI API key format' : 'Should start with sk- and be at least 20 chars'
    };
  }
};

function validateEnvironmentFormats() {
  console.log('🔍 Validating Environment Variable Formats...\n');

  let hasErrors = false;

  Object.entries(formatValidators).forEach(([varName, validator]) => {
    const value = process.env[varName];
    const result = validator(value);

    const status = result.valid ? '✅' : '❌';
    console.log(`${status} ${varName}: ${result.message}`);

    if (!result.valid) {
      hasErrors = true;
      if (value) {
        console.log(`   Current value: ${value.substring(0, 20)}${value.length > 20 ? '...' : ''}`);
      }
    }
  });

  console.log('\n' + '='.repeat(60));

  if (hasErrors) {
    console.log('❌ Format validation found issues');
    console.log('Please fix the environment variable formats above');
  } else {
    console.log('✅ All environment variable formats are valid');
  }

  return !hasErrors;
}

// Run if executed directly
if (require.main === module) {
  validateEnvironmentFormats();
}

module.exports = { validateEnvironmentFormats, formatValidators };

