{
  "name": "secure-node-app",
  "version": "1.0.0",
  "description": "Security-hardened Node.js application",
  "main": "app.js",
  "scripts": {
    "start": "node app.js",
    "dev": "nodemon app.js",
    "test": "echo \"Error: no test specified\" && exit 1"
  },
  "dependencies": {
    "express": "^4.18.2",
    "helmet": "^7.0.0",
    "cors": "^2.8.5",
    "express-rate-limit": "^6.8.1",
    "express-validator": "^7.0.1",
    "morgan": "^1.10.0",
    "dotenv": "^16.3.1"
  },
  "devDependencies": {
    "nodemon": "^3.0.1"
  },
  "engines": {
    "node": ">=18.0.0"
  },
  "keywords": ["security", "express", "nodejs"],
  "author": "Security Team",
  "license": "MIT"
}

// Security-hardened Node.js Express application
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// CORS configuration
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// Logging
app.use(morgan('combined'));

// Body parsing middleware
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Secure users endpoint with validation
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
], validateRequest, (req, res) => {
  // Mock user data (in real app, this would come from a secure database)
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: new Date().toISOString()
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: new Date().toISOString()
    },
  ];

  // Apply pagination if requested
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    users: paginatedUsers,
    total: users.length,
    limit,
    offset
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Something went wrong!'
    });
  }

  res.status(500).json({ 
    error: err.message,
    stack: err.stack
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);

  // Security check - warn if running in production without proper env
  if (process.env.NODE_ENV === 'production') {
    if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET === 'generatelongrandomsecrethere') {
      console.warn('⚠️  WARNING: Using default session secret in production!');
    }
  }
});

module.exports = app;

#!/usr/bin/env node

// Simple security audit script for Node.js projects
const fs = require('fs');
const path = require('path');

console.log('🔍 Running Security Audit...\n');

// Check 1: Environment files
console.log('1. Checking environment files...');
try {
  if (fs.existsSync('.env')) {
    console.log('   ❌ .env file found - should not be in version control');
  } else {
    console.log('   ✅ No .env file found');
  }

  if (fs.existsSync('.env.test')) {
    const content = fs.readFileSync('.env.test', 'utf8');
    if (content.includes('CANARY') || content.includes('secret')) {
      console.log('   ⚠️  .env.test contains test credentials - ensure this is in .gitignore');
    }
  }
} catch (error) {
  console.log('   ✅ No environment files found');
}

// Check 2: package.json
console.log('\n2. Checking package.json...');
try {
  if (fs.existsSync('package.json')) {
    const pkg = JSON.parse(fs.readFileSync('package.json', 'utf8'));

    // Check for security dependencies
    const securityDeps = ['helmet', 'cors', 'express-rate-limit', 'express-validator'];
    const missingDeps = securityDeps.filter(dep => !pkg.dependencies || !pkg.dependencies[dep]);

    if (missingDeps.length > 0) {
      console.log(`   ⚠️  Missing security dependencies: ${missingDeps.join(', ')}`);
    } else {
      console.log('   ✅ Security dependencies present');
    }

  } else {
    console.log('   ❌ package.json not found');
  }
} catch (error) {
  console.log('   ❌ Error reading package.json');
}

// Check 3: .gitignore
console.log('\n3. Checking .gitignore...');
try {
  if (fs.existsSync('.gitignore')) {
    const gitignore = fs.readFileSync('.gitignore', 'utf8');
    const requiredPatterns = [
      '.env',
      'node_modules',
      'npm-debug',
      '.DS_Store'
    ];

    const missingPatterns = requiredPatterns.filter(pattern => 
      !gitignore.includes(pattern)
    );

    if (missingPatterns.length > 0) {
      console.log(`   ⚠️  Missing .gitignore patterns: ${missingPatterns.join(', ')}`);
    } else {
      console.log('   ✅ .gitignore looks good');
    }

  } else {
    console.log('   ❌ .gitignore not found');
  }
} catch (error) {
  console.log('   ❌ Error reading .gitignore');
}

// Check 4: Node version
console.log('\n4. Checking Node.js version...');
console.log(`   ℹ️  Current Node version: ${process.version}`);
if (parseInt(process.version.slice(1).split('.')[0]) < 16) {
  console.log('   ⚠️  Using older Node.js version - consider upgrading to LTS');
} else {
  console.log('   ✅ Node.js version is recent');
}

console.log('\n🔒 Audit completed. Review recommendations above.');
console.log('\nNext steps:');
console.log('1. Run npm audit');
console.log('2. Review dependencies for vulnerabilities');
console.log('3. Implement security middleware');
console.log('4 Set up proper environment configuration');

