// Security-hardened Node.js Express application with environment configuration
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();

// Configuration from environment variables
const config = {
  port: parseInt(process.env.PORT) || 3000,
  environment: process.env.NODE_ENV || 'development',
  corsOrigin: process.env.CORS_ORIGIN,
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000, // 15 minutes default
  rateLimitMax: parseInt(process.env.RATE_LIMIT_MAX) || 100,
  requestSizeLimit: process.env.REQUEST_SIZE_LIMIT || '10kb',
  enableRateLimiting: process.env.ENABLE_RATE_LIMITING !== 'false', // enabled by default
  enableCors: process.env.ENABLE_CORS !== 'false', // enabled by default
};

// Security middleware
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
    },
  },
}));

// CORS configuration
if (config.enableCors) {
  if (!config.corsOrigin && config.environment === 'production') {
    console.warn('⚠️  WARNING: CORS_ORIGIN not set in production!');
  }

  app.use(cors({
    origin: config.corsOrigin || (config.environment === 'production' ? false : 'http://localhost:3000'),
    credentials: true
  }));
}

// Rate limiting
if (config.enableRateLimiting) {
  const limiter = rateLimit({
    windowMs: config.rateLimitWindowMs,
    max: config.rateLimitMax,
    message: 'Too many requests from this IP, please try again later.'
  });
  app.use(limiter);
}

// Logging
app.use(morgan(config.environment === 'production' ? 'combined' : 'dev'));

// Body parsing middleware
app.use(express.json({ limit: config.requestSizeLimit }));
app.use(express.urlencoded({ extended: true, limit: config.requestSizeLimit }));

// Input validation middleware
const validateRequest = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: config.environment,
    config: {
      rateLimiting: config.enableRateLimiting,
      cors: config.enableCors
    }
  });
});

// Secure users endpoint with validation
app.get('/users', [
  // Validate query parameters
  body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100'),
  body('offset').optional().isInt({ min: 0 }).withMessage('Offset must be a positive integer')
], validateRequest, (req, res) => {
  // Mock user data (in real app, this would come from a secure database)
  const users = [
    { 
      id: 1, 
      name: 'Alice', 
      email: 'alice@example.com',
      createdAt: new Date().toISOString()
    },
    { 
      id: 2, 
      name: 'Bob', 
      email: 'bob@example.com',
      createdAt: new Date().toISOString()
    },
  ];

  // Apply pagination if requested
  const limit = parseInt(req.query.limit) || 10;
  const offset = parseInt(req.query.offset) || 0;
  const paginatedUsers = users.slice(offset, offset + limit);

  res.json({
    users: paginatedUsers,
    total: users.length,
    limit,
    offset,
    environment: config.environment
  });
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  if (config.environment === 'production') {
    return res.status(500).json({ 
      error: 'Internal Server Error',
      message: 'Something went wrong!'
    });
  }

  res.status(500).json({ 
    error: err.message,
    stack: err.stack
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    message: `Route ${req.originalUrl} not found`
  });
});

app.listen(config.port, () => {
  console.log(`Server running on port ${config.port} in ${config.environment} mode`);
  console.log(`Configuration:`);
  console.log(`- CORS: ${config.enableCors ? 'Enabled' : 'Disabled'}`);
  console.log(`- Rate Limiting: ${config.enableRateLimiting ? 'Enabled' : 'Disabled'}`);
  console.log(`- Request Size Limit: ${config.requestSizeLimit}`);

  // Security warnings
  if (config.environment === 'production') {
    if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET === 'generatelongrandomsecrethere') {
      console.warn('⚠️  WARNING: Using default session secret in production!');
    }
    if (!config.corsOrigin) {
      console.warn('⚠️  WARNING: CORS_ORIGIN not configured for production!');
    }
  }
});

module.exports = app;

#!/usr/bin/env node

// Environment configuration validator
const fs = require('fs');
const path = require('path');

console.log('🔍 Validating Environment Configuration...\n');

// Required environment variables for production
const requiredProductionVars = [
  'NODE_ENV',
  'SESSION_SECRET',
  'CORS_ORIGIN'
];

// Recommended environment variables
const recommendedVars = [
  'PORT',
  'RATE_LIMIT_WINDOW_MS',
  'RATE_LIMIT_MAX',
  'REQUEST_SIZE_LIMIT',
  'ENABLE_RATE_LIMITING',
  'ENABLE_CORS'
];

// Check if .env file exists
if (!fs.existsSync('.env')) {
  console.log('❌ No .env file found');
  console.log('💡 Run: cp .env.example .env');
  process.exit(1);
}

// Read .env file
const envContent = fs.readFileSync('.env', 'utf8');
const envVars = {};

// Parse environment variables
envContent.split('\n').forEach(line => {
  line = line.trim();
  if (line && !line.startsWith('#')) {
    const [key, value] = line.split('=');
    if (key && value) {
      envVars[key.trim()] = value.trim();
    }
  }
});

console.log('📋 Current Environment Configuration:');
console.log('====================================');

// Check NODE_ENV
const nodeEnv = envVars.NODE_ENV || 'development';
console.log(`🌐 NODE_ENV: ${nodeEnv}`);

// Check required variables for production
if (nodeEnv === 'production') {
  console.log('\n🔒 Production Environment Checks:');
  console.log('================================');

  let productionIssues = false;

  requiredProductionVars.forEach(varName => {
    if (!envVars[varName] || envVars[varName] === '') {
      console.log(`❌ ${varName}: Missing or empty`);
      productionIssues = true;
    } else if (varName === 'SESSION_SECRET' && envVars[varName].includes('generatelongrandomsecrethere')) {
      console.log(`❌ ${varName}: Using default value in production!`);
      productionIssues = true;
    } else {
      console.log(`✅ ${varName}: Configured`);
    }
  });

  if (productionIssues) {
    console.log('\n🚨 CRITICAL: Production environment not properly configured!');
  }
}

// Check recommended variables
console.log('\n📊 Recommended Configuration Checks:');
console.log('==================================');

recommendedVars.forEach(varName => {
  if (envVars[varName] === undefined || envVars[varName] === '') {
    console.log(`⚠️  ${varName}: Not configured (using default)`);
  } else {
    console.log(`✅ ${varName}: Configured`);
  }
});

// Security checks
console.log('\n🔐 Security Checks:');
console.log('==================');

// Check for default secrets
if (envVars.SESSION_SECRET && envVars.SESSION_SECRET.includes('generatelongrandomsecrethere')) {
  console.log('❌ SESSION_SECRET: Using default value - generate a random secret!');
} else if (envVars.SESSION_SECRET) {
  console.log('✅ SESSION_SECRET: Custom value set');
}

// Check port configuration
if (envVars.PORT && envVars.PORT === '3000') {
  console.log('ℹ️  PORT: Using default port 3000');
}

console.log('\n📝 Summary:');
console.log('==========');

const totalVars = Object.keys(envVars).length;
const configuredVars = Object.values(envVars).filter(v => v && v !== '').length;

console.log(`Total environment variables: ${totalVars}`);
console.log(`Configured variables: ${configuredVars}`);
console.log(`Configuration completeness: ${Math.round((configuredVars / totalVars) * 100)}%`);

if (nodeEnv === 'production') {
  console.log('\n💡 Production Tips:');
  console.log('- Use different credentials for each environment');
  console.log('- Set NODE_ENV=production');
  console.log('- Use strong, randomly generated secrets');
  console.log('- Configure proper CORS origins');
  console.log('- Enable all security features');
}

console.log('\n✅ Environment validation completed');

