// Secure application with environment variables
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');

const app = express();

// Environment configuration
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const isProduction = NODE_ENV === 'production';

// Security middleware
app.use(helmet());
app.use(rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: isProduction ? 100 : 1000 // different limits for dev/prod
}));

// CORS configuration
app.use(cors({
  origin: isProduction 
    ? (process.env.ALLOWED_ORIGINS || '').split(',')
    : ['http://localhost:3000', 'http://127.0.0.1:3000']
}));

// Parse JSON bodies
app.use(express.json({ limit: '10kb' }));

// Routes
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

app.get('/users', (req, res) => {
  // Users could come from environment variable or database
  const users = process.env.TEST_USERS 
    ? JSON.parse(process.env.TEST_USERS)
    : [
        { id: 1, name: 'Alice', email: 'a***e@example.com' },
        { id: 2, name: 'Bob', email: 'b**@example.com' },
      ];

  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);
  res.status(500).json({ 
    error: isProduction ? 'Internal server error' : err.message 
  });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Route not found' });
});

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

module.exports = app;

